import React, { useState } from 'react'

function UseMemoHook() {
    const[count,setCount]=useState(0)
    const[color,setColor]=useState("blue")
        function getNumber(){
            console.log("get number func")

            return count * 10
        }
        let myNumber
  return (
   <>
   <h1>usememo() hook</h1>
   <h2>count:{count}</h2>
   <button onClick={()=> setCount(count+1)}>change count</button>
   <div style={{background:color,height:"200px",width:"300px"}}></div>
   <button onClick={()=> setColor("blue"? "red" : "blue")}>change color</button>
   <h2>number :{myNumber}</h2>
   </>
  )
}

export default UseMemoHook
